"""L400 lesson 17 (python quorum.py): consistency models in practice with a quorum-replicated register.
N=3 replicas in zones A, B (one region) and C (another region); a single writer and three readers in different
zones, on a seeded simulated network (helpers.Sim; simulated ms, no sleeps). For each (R, W) we measure read and
write latency, stale reads, read-your-writes violations, new-then-old inversions and availability with a
region down - then decide per use case. The lesson file returns the newest of R replies and nothing else."""
import json

from helpers import Sim, anomalies, pct

REPLICAS, TIMEOUT_MS, RUN_MS = ("a", "b", "c"), 300.0, 10000.0
CLIENTS = {"writer": "A", "r1": "A", "r2": "B", "r3": "C", "r4": "A", "r5": "B", "r6": "C"}  # client -> its zone
SETTINGS = [(1, 1, False), (1, 2, False), (2, 2, False), (1, 3, False), (3, 1, False), (2, 2, True)]  # (R, W, write-back)


class Cluster:
    def __init__(self, sim, r, w, write_back=False):
        self.sim, self.r, self.w, self.write_back = sim, r, w, write_back
        self.version = {rep: 0 for rep in REPLICAS}  # each replica keeps the newest version it has seen

    def write(self, zone, version, done):
        """Send to all N replicas, succeed after W acks (Dynamo: latency = the W-th fastest replica)."""
        state = {"acks": 0, "over": False}

        def at_replica(back, rep):
            self.version[rep] = max(self.version[rep], version)  # apply, then ack
            self.sim.at(back, ack)

        def ack():
            state["acks"] += 1
            if state["acks"] == self.w and not state["over"]:
                state["over"] = True
                done(True, version)
        self._fan_out(zone, at_replica, state, done, version)

    def read(self, zone, done):
        """Ask all N replicas, use the first R replies (the R fastest decide the latency)."""
        state, replies = {"over": False}, []

        def at_replica(back, rep):
            self.sim.at(back, reply, self.version[rep])

        def reply(v):
            replies.append(v)
            if len(replies) == self.r and not state["over"]:
                state["over"] = True
                self.finish_read(zone, replies, done)
        self._fan_out(zone, at_replica, state, done, None)

    def finish_read(self, zone, replies, done):
        done(True, max(replies))  # newest of the R replies; write_back is ignored, so later reads may see older

    def _fan_out(self, zone, at_replica, state, done, value):
        for rep in REPLICAS:
            self.sim.send(zone, rep, at_replica, rep)

        def timeout():  # fewer than R (or W) replicas answered: the operation fails (unavailable)
            if not state["over"]:
                state["over"] = True
                done(False, value)
        self.sim.at(self.sim.now + TIMEOUT_MS, timeout)


def run(r, w, seed=17, down=(), cluster_class=Cluster, write_back=False, run_ms=RUN_MS):
    """Closed-loop clients start ops for run_ms, then the run drains: every op ends (ok or timed out).
    The writer writes v+1 then reads it back; readers read and think."""
    sim, history = Sim(seed), []
    sim.down |= set(down)
    cluster, next_version = cluster_class(sim, r, w, write_back), [0]

    def start(proc, f):
        if sim.now > run_ms:
            return
        op = {"process": proc, "f": f, "start": sim.now}

        def done(ok, value):
            op.update(ok=ok, value=value, end=sim.now)
            history.append(op)
            again = "read" if proc == "writer" and f == "write" else ("write" if proc == "writer" else "read")
            sim.at(sim.now + sim.rng.expovariate(1 / (20.0 if again == "write" else 5.0)), start, proc, again)
        if f == "write":
            next_version[0] += 1
            cluster.write(CLIENTS[proc], next_version[0], done)
        else:
            cluster.read(CLIENTS[proc], done)

    for proc in CLIENTS:
        sim.at(sim.rng.uniform(0, 5), start, proc, "write" if proc == "writer" else "read")
    sim.run(float("inf"))
    return history


def measure(r, w, write_back=False, seed=17, cluster_class=Cluster):
    history = run(r, w, seed, cluster_class=cluster_class, write_back=write_back)
    lat = {f: [op["end"] - op["start"] for op in history if op["ok"] and op["f"] == f] for f in ("read", "write")}
    a = anomalies(history)
    region_down = run(r, w, seed, down=("c",), cluster_class=cluster_class, write_back=write_back)
    avail = min(100 * sum(op["ok"] for op in region_down if op["f"] == f) / sum(op["f"] == f for op in region_down)
                for f in ("read", "write"))  # the worse of read and write availability
    return {"R": r, "W": w, "write_back": write_back, "overlap": r + w > len(REPLICAS), "read_p50": pct(lat["read"], 50),
            "read_p99": pct(lat["read"], 99), "write_p99": pct(lat["write"], 99),
            "stale_pct": round(100 * a["stale"] / a["reads"], 2), "stale_age_max": a["age_max"], "ryw": a["ryw"], "inversions": a["inversions"],
            "linearizable": a["stale"] == 0 and a["inversions"] == 0,
            "avail_c_down_pct": round(avail, 1)}


USE_CASES = {  # constraints from the design brief; decide() picks the fastest setting that meets them
    "cart badge (shows a count)": {"max_stale_pct": 20.0, "read_p99_ms": 70.0, "write_p99_ms": 40.0, "min_avail_pct": 99.0},
    "feature flag (writer sees own change)": {"max_stale_pct": 1.0, "ryw": True, "read_p99_ms": 80.0,
                                              "write_p99_ms": 100.0, "min_avail_pct": 99.0},
    "lock owner / config (linearizable)": {"linearizable": True, "read_p99_ms": 150.0, "write_p99_ms": 100.0,
                                           "min_avail_pct": 99.0},
}


def decide(rows, need):
    ok = [m for m in rows if m["stale_pct"] <= need.get("max_stale_pct", 0.0) and m["read_p99"] <= need["read_p99_ms"]
          and m["write_p99"] <= need["write_p99_ms"]
          and m["avail_c_down_pct"] >= need["min_avail_pct"] and (m["linearizable"] or not need.get("linearizable"))
          and (m["ryw"] == 0 or not need.get("ryw"))]
    return min(ok, key=lambda m: (m["read_p99"], m["write_p99"]), default=None)


def main(cluster_class=Cluster):
    rows = [measure(r, w, wb, cluster_class=cluster_class) for r, w, wb in SETTINGS]
    print("N R W wb R+W>N  read p50/p99 ms  write p99  stale% (max age ms)  ryw  inversions  linearizable  avail, C down")
    for m in rows:
        print(f"3 {m['R']} {m['W']} {'+' if m['write_back'] else '-':2} {str(m['overlap']):6} {m['read_p50']:>7}/{m['read_p99']:<6} {m['write_p99']:>9}"
              f" {m['stale_pct']:>6} ({m['stale_age_max']:>5}) {m['ryw']:>9} {m['inversions']:>10}  {str(m['linearizable']):12}"
              f" {m['avail_c_down_pct']:>6}%")
    for name, need in USE_CASES.items():
        best = decide(rows, need)
        choice = f"N=3 R={best['R']} W={best['W']}" + (" + read write-back" if best["write_back"] else "") if best else None
        print(f"decide {name}: {choice or 'NO setting meets the constraints'}")
    return rows


if __name__ == "__main__":
    print(json.dumps({"seed": 17, "run_ms": RUN_MS, "replicas": "a@A b@B c@C (C = other region)"}))
    main()

"""L400 lesson 18 (python crdts.py): state-based CRDTs for local-first collaboration.
G-Counter, PN-Counter, OR-Set and LWW-Register (Shapiro et al., 2011): every replica updates locally (offline
is fine) and merge() is a join - commutative, associative, idempotent - so replicas that have seen the same updates
hold the same state, whatever order, duplication or path the sync took. helpers.py generates seeded random
histories and checks those laws; this file shows a two-phone story, the property results and the options."""
import json, random

from helpers import check_laws, converge, size


class GCounter:  # grow-only: one slot per replica, merge = per-slot max (vector-clock shape)
    def __init__(self, slots=None):
        self.slots = dict(slots or {})

    def inc(self, replica, n=1):
        self.slots[replica] = self.slots.get(replica, 0) + n  # a replica only ever touches its own slot

    def value(self):
        return sum(self.slots.values())

    def merge(self, other):
        keys = self.slots.keys() | other.slots.keys()
        return GCounter({k: max(self.slots.get(k, 0), other.slots.get(k, 0)) for k in keys})

    def state(self):
        return sorted(self.slots.items())


class PNCounter:  # increments and decrements = two G-Counters
    def __init__(self, p=None, n=None):
        self.p, self.n = p or GCounter(), n or GCounter()

    def add(self, replica, delta):
        (self.p if delta >= 0 else self.n).inc(replica, abs(delta))

    def value(self):
        return self.p.value() - self.n.value()

    def merge(self, other):
        return PNCounter(self.p.merge(other.p), self.n.merge(other.n))

    def state(self):
        return self.p.state(), self.n.state()


class ORSet:  # observed-remove set: add-wins; every add gets a unique tag, remove tombstones the tags it saw
    def __init__(self, adds=None, tombs=None):
        self.adds, self.tombs = {e: set(t) for e, t in (adds or {}).items()}, set(tombs or ())

    def add(self, element, tag):
        self.adds.setdefault(element, set()).add(tag)  # tag = (replica, counter): unique per add

    def remove(self, element):
        self.tombs |= self.adds.get(element, set())  # only tags observed HERE: a concurrent add survives

    def value(self):
        return {e for e, tags in self.adds.items() if tags - self.tombs}

    def merge(self, other):
        adds = {e: self.adds.get(e, set()) | other.adds.get(e, set()) for e in self.adds.keys() | other.adds.keys()}
        return ORSet(adds, self.tombs | other.tombs)

    def state(self):
        return sorted((e, sorted(t)) for e, t in self.adds.items()), sorted(self.tombs)


class LWWRegister:  # last-writer-wins by Lamport timestamp; the replica id travels with the value
    def __init__(self, value=None, ts=0, replica=""):
        self.val, self.ts, self.replica = value, ts, replica

    def assign(self, replica, value, seen_ts):
        self.val, self.ts, self.replica = value, max(self.ts, seen_ts) + 1, replica

    def value(self):
        return self.val

    def merge(self, other):
        if other.ts > self.ts:  # BUG (failure lab): equal timestamps keep MY value -> merge is not commutative
            return LWWRegister(other.val, other.ts, other.replica)
        return LWWRegister(self.val, self.ts, self.replica)

    def state(self):
        return self.val, self.ts, self.replica


class LWWCounter(LWWRegister):  # option "store the number, last writer wins": concurrent increments get lost
    def add(self, replica, delta):
        self.assign(replica, (self.val or 0) + delta, self.ts)

    def merge(self, other):
        won = LWWRegister.merge(self, other)
        return LWWCounter(won.val, won.ts, won.replica)


TYPES = {"G-Counter": GCounter, "PN-Counter": PNCounter, "OR-Set": ORSet, "LWW-Register": LWWRegister}


def two_phones():
    """Two devices edit a shared shopping list offline, then sync both ways."""
    phone, laptop = ORSet(), ORSet()
    phone.add("milk", ("phone", 1))
    laptop = laptop.merge(phone)
    phone.remove("milk")  # phone removes milk ...
    laptop.add("milk", ("laptop", 1))  # ... while the laptop re-adds it (concurrently): add wins
    laptop.add("eggs", ("laptop", 2))
    return phone.merge(laptop), laptop.merge(phone)


def like_counter(seed=18, steps=300):
    """Options for a shared like-counter: 3 replicas, random sync, 20% of syncs delivered twice."""
    rng, truth = random.Random(seed), 0
    reps = {"lww": [LWWCounter() for _ in range(3)], "pn": [PNCounter() for _ in range(3)]}
    for _ in range(steps):
        i, j, delta = rng.randrange(3), rng.randrange(3), rng.choice((1, 1, 1, -1))
        truth += delta
        for rs in reps.values():
            rs[i].add(f"r{i}", delta)
        if rng.random() < 0.5:
            for _ in range(2 if rng.random() < 0.2 else 1):
                for rs in reps.values():
                    rs[j] = rs[j].merge(rs[i])
    for rs in reps.values():  # final anti-entropy: everyone merges everyone
        for x in range(3):
            for y in range(3):
                rs[y] = rs[y].merge(rs[x])
    return {"truth": truth, **{k: [r.value() for r in rs] for k, rs in reps.items()},
            "bytes": {k: size(rs[0]) for k, rs in reps.items()}}


if __name__ == "__main__":
    a, b = two_phones()
    print(f"1) phone+laptop: {sorted(a.value())} == {sorted(b.value())}: {a.state() == b.state()}")
    print("2) merge laws and convergence over 500 seeded random histories per type:")
    for name, cls in TYPES.items():
        laws, conv = check_laws(cls, seed=18), converge(cls, seed=18)
        print(f"   {name:13} {json.dumps({**laws['counts'], 'converged': conv['converged']})}")
        for example in filter(None, (laws["counterexample"], conv["counterexample"])):
            print(f"   {'':13} shrunk counterexample: {example}")
    c = like_counter()
    print(f"3) like-counter, truth {c['truth']}: LWW number {c['lww']} (concurrent adds lost), PN-Counter {c['pn']};"
          f" sync bytes LWW {c['bytes']['lww']}, PN {c['bytes']['pn']}")

"""L400 lesson 20 (python chaos.py): hypothesis-driven chaos experiments against the L300 labs.
Targets: the L300 saga (lesson 14) and Raft (lesson 12), each as shipped in L300 (unhardened) and as hardened by
its build task. Every experiment states a steady-state metric and a hypothesis, injects a seeded real-world fault and
tries to refute the hypothesis (Principles of Chaos). Results are JSON lines. The lesson's saga harness injects the
fault into EVERY order, keeps no control group and never aborts - watch how many customers the experiment hurts."""
import random

from harness import cohort, jsonl, load

SAGA = {"L300 lesson": load("14-sagas-compensation/saga.py", "l300_saga"),
        "L300 hardened": load("14-sagas-compensation/solution_saga.py", "l300_saga_hardened")}
RAFT = {"L300 lesson": load("12-raft-replicated-log/raft.py", "l300_raft"),
        "L300 hardened": load("12-raft-replicated-log/solution_raft.py", "l300_raft_hardened")}
N_ORDERS, BLAST_PCT, ABORT_AFTER = 60, 10.0, 1  # blast-radius limit and abort rule (used once you add them)


def harmed(mod, services, log, sagas):
    """Steady-state metric, from the services' own data: orders whose money/state is wrong or never finished."""
    bad = {line.split(":")[0] for line in mod.audit(*services)}
    unfinished = {s for s in sagas if not any(r["step"] == "saga" and r["status"] in ("completed", "compensated")
                                              for r in log.entries(s))}
    return sorted((bad | unfinished) & set(sagas))


def inject(mod, orch, shipping, fault, saga):
    """Real-world faults: the courier API is down for this order, or the orchestrator dies right after a charge."""
    if fault == "shipping-outage":
        shipping.outcome[saga] = "no courier slot"
    elif fault == "crash-after-charge":
        name, charge, comp = orch.steps[1]

        def dies_after(s, amount):
            charge(s, amount)
            if s == saga:
                raise mod.lab_helpers.Crash(f"orchestrator died after charge({s})")
        orch.steps[1] = (name, dies_after, comp)


def run_saga_experiment(target, fault, seed):
    """Lesson harness: fault on every order (blast radius 100%), no control group, no abort rule."""
    mod = SAGA[target]
    services, log = (mod.Orders(), mod.Payments(), mod.Shipping(0.0, seed)), mod.lab_helpers.SagaLog()
    orch, sagas = mod.Orchestrator(*services, log), [f"o{i}" for i in range(1, N_ORDERS + 1)]
    for i, saga in enumerate(sagas, start=1):
        steps = list(orch.steps)
        inject(mod, orch, services[2], fault, saga)
        try:
            orch.run(saga, 10 * i)
        except mod.lab_helpers.Crash:
            if hasattr(orch, "recover"):
                orch.recover()  # the supervisor restarts the orchestrator; it finishes from the saga log
        orch.steps = steps
    hurt = harmed(mod, services, log, sagas)
    return {"experiment": f"saga/{fault}", "target": target, "seed": seed, "blast_radius_pct": 100.0,
            "steady_state": "harmed orders = 0", "experiment_harmed": len(hurt), "control_harmed": None,
            "held": not hurt, "aborted": False, "customers_hurt": len(hurt)}


def run_raft_experiment(target, fault, seed, ticks=60, settle=(0, 4)):
    """Raft faults touch one node at a time (a minority): random crashes, or a fast rolling restart that waits
    only 0-4 ticks between nodes. Steady state: no committed entry lost, a leader again within 40 ticks."""
    mod, rng = RAFT[target], random.Random(f"{fault}-{seed}")
    c, t, gap, worst = mod.lab_helpers.Cluster(mod.Node, seed), 0, 0, 0
    c.run_until_leader()

    def step(n):
        nonlocal t, gap, worst
        for _ in range(n):
            if t % 2 == 0 and c.leader():
                c.leader().propose(f"x={t}")  # steady write load
            c.run(1)
            t, gap = t + 1, (gap + 1 if c.leader() is None else 0)
            worst = max(worst, gap)
    step(10)
    if fault == "rolling-restart":
        for name in sorted(c.nodes, key=lambda n: c.nodes[n].role == "leader"):  # followers first, leader last
            c.crash(name)
            step(12)
            c.restart(name)
            step(rng.randint(*settle))  # impatient rollout (0-4 ticks): does not wait for the node to catch up
    else:  # random-crash: 8 crashes of a random node (the leader 60% of the time), down 5-30 ticks each
        for _ in range(8):
            leader = c.leader()
            name = leader.name if leader and rng.random() < 0.6 else rng.choice(sorted(c.nodes))
            c.crash(name)
            step(rng.randint(5, 30))
            c.restart(name)
            step(rng.randint(5, 20))
    step(ticks)
    lost = len(c.checker.violations)
    return {"experiment": f"raft/{fault}", "target": target, "seed": seed, "blast_radius_pct": 33.3,
            "steady_state": "lost committed entries = 0, no-leader gap <= 40 ticks", "lost_entries": lost,
            "max_no_leader_ticks": worst, "held": lost == 0 and worst <= 40}


def campaign():
    rows = [run_saga_experiment(t, f, 14) for t in SAGA for f in ("shipping-outage", "crash-after-charge")]
    rows += [run_raft_experiment(t, f, s) for t in RAFT for f in ("random-crash", "rolling-restart") for s in range(1, 21)]
    return rows


def summary(rows):
    out = {}
    for r in rows:
        k = (r["experiment"], r["target"])
        held, runs, hurt = out.get(k, (0, 0, 0))
        out[k] = (held + r["held"], runs + 1, hurt + r.get("customers_hurt", 0))
    return out


if __name__ == "__main__":
    rows = campaign()
    print(*jsonl([r for r in rows if r["experiment"].startswith("saga")]), sep="\n")
    print("experiment              target          hypothesis held   customers hurt by the experiment")
    for (exp, target), (held, runs, hurt) in summary(rows).items():
        print(f"{exp:23} {target:15} {held:>3}/{runs:<3} runs {hurt:>12}")

"""L400 lesson 21 (python modelcheck.py): find a protocol bug automatically by exhaustive model checking.
A toy leader election (Raft's voting rule, 3 nodes, terms up to 2) is written as a state machine: a state is an
immutable tuple, actions produce successor states. bfs() visits EVERY reachable state, checks the invariants in
each and returns the SHORTEST trace to a violation - what TLC does for a TLA+ spec (Election.tla is the same model).
The lesson protocol keeps votedFor only in memory, so a restart forgets the vote."""
import random, time
from collections import deque

NODES, MAX_TERM = (0, 1, 2), 2
PERSIST_VOTE = False  # the bug: a restarted node forgets whom it voted for in its current term


def init():
    # per node: (term, voted_for, role, votes received); plus a ghost log of every vote ever cast (term, voter, cand)
    return tuple((0, None, "follower", frozenset()) for _ in NODES), frozenset()


def replace(nodes, i, node):
    return nodes[:i] + (node,) + nodes[i + 1:]


def actions(state):
    """Every enabled step: (label, next_state). Messages are delivered atomically (request + reply in one step)."""
    nodes, cast = state
    for i, (term, voted, role, votes) in enumerate(nodes):
        if role != "leader" and term < MAX_TERM:  # election timeout: new term, vote for myself
            yield f"n{i} times out -> candidate, term {term + 1}", (
                replace(nodes, i, (term + 1, i, "candidate", frozenset({i}))), cast | {(term + 1, i, i)})
        if role == "candidate" and 2 * len(votes) > len(NODES):
            yield f"n{i} becomes leader of term {term}", (replace(nodes, i, (term, voted, "leader", votes)), cast)
        if role == "candidate":
            for j in NODES:
                if j in votes or j == i:
                    continue
                jt, jv, jr, jvotes = nodes[j]
                if jt > term:
                    continue  # j is in a newer term: it refuses (and i would step down later)
                if jt < term:  # newer term seen: j becomes a follower with no vote in that term yet
                    jt, jv, jr, jvotes = term, None, "follower", frozenset()
                if jv in (None, i):  # one vote per term, first come first served
                    nxt = replace(replace(nodes, j, (jt, i, jr, jvotes)), i, (term, voted, role, votes | {j}))
                    yield f"n{j} votes for n{i} in term {term}", (nxt, cast | {(term, j, i)})
    for j, (term, voted, role, votes) in enumerate(nodes):  # crash + restart: volatile state is lost
        kept = voted if PERSIST_VOTE else None
        restarted = (term, kept, "follower", frozenset())
        if restarted != nodes[j]:
            yield f"n{j} restarts (votedFor {'kept' if PERSIST_VOTE else 'forgotten'})", (replace(nodes, j, restarted), cast)


def election_safety(state):
    """At most one leader per term (Raft, Figure 3)."""
    leaders = [(t, i) for i, (t, _, role, _) in enumerate(state[0]) if role == "leader"]
    return len({t for t, _ in leaders}) == len(leaders)


INVARIANTS = {"ElectionSafety": election_safety}


def bfs(invariants=None):
    """Explicit-state breadth-first search. Returns (violated invariant or None, shortest trace, states, ms)."""
    invariants, start = invariants or INVARIANTS, time.perf_counter()
    first = init()
    parent, queue = {first: None}, deque([first])
    while queue:
        state = queue.popleft()
        for name, ok in invariants.items():
            if not ok(state):
                trace = []
                while parent[state]:
                    state, label = parent[state]
                    trace.append(label)
                return name, trace[::-1], len(parent), round(1000 * (time.perf_counter() - start))
        for label, nxt in actions(state):
            if nxt not in parent:
                parent[nxt] = (state, label)
                queue.append(nxt)
    return None, [], len(parent), round(1000 * (time.perf_counter() - start))


def random_walks(walks=1000, depth=30, seed=21):
    """The cheaper alternative: random simulation. How many walks hit the bug, and how long is the first trace?"""
    rng, hits, shortest = random.Random(seed), 0, None
    for _ in range(walks):
        state = init()
        for step in range(1, depth + 1):
            options = list(actions(state))
            if not options:
                break
            state = rng.choice(options)[1]
            if not all(ok(state) for ok in INVARIANTS.values()):
                hits, shortest = hits + 1, min(shortest or step, step)
                break
    return hits, shortest


if __name__ == "__main__":
    violated, trace, states, ms = bfs()
    print(f"BFS: {states} distinct states explored, invariant {violated or 'none'} violated")
    for k, label in enumerate(trace, start=1):
        print(f"  {k}. {label}")
    hits, shortest = random_walks()
    print(f"random simulation: bug hit in {hits}/1000 walks of <= 30 steps (shortest {shortest or '-'} steps)")

"""Capstone (python pipeline.py): an order pipeline built from the earlier labs, on simulated ticks, seeded.
gateway (bounded queue, 503 + Retry-After; L300 #16) -> workers -> orchestrated saga create/charge/ship with
compensation and recover() (L300 #14) -> every state change + its event in one outbox transaction -> relay ->
at-least-once bus -> idempotent consumers (email, revenue). Every order carries a W3C trace context (L300 #15);
the gateway's queue bound is replicated config committed through Raft (L300 #12). Faults are switched on by name."""
import random
from collections import Counter, defaultdict, deque

from outbox import Bus, IdempotentConsumer, OutboxDB, Relay
from reuse import BACKPRESSURE, RAFT, SAGA, TRACING

EVENTS = {"create": "order.created", "cancel": "order.cancelled", "charge": "payment.charged",
          "refund": "payment.refunded", "ship": "shipment.shipped"}
OWNER = {"create": "orders", "cancel": "orders", "charge": "payments", "refund": "payments", "ship": "shipping"}
CONFIG_CHANGES = {0: 8, 25: 12}  # tick -> wanted max_queue (an operator raises the bound at tick 25)
WORKERS, N_ORDERS, MAX_TICKS = 3, 60, 300


class Pipeline:
    def __init__(self, seed=22, faults=(), cohort=frozenset()):
        self.rng, self.t, self.faults, self.cohort = random.Random(seed), 0, set(faults), cohort
        self.raft, self.config = RAFT.lab_helpers.Cluster(RAFT.Node, seed), {"version": 0, "max_queue": 1}
        self.orders, self.payments, self.shipping = SAGA.Orders(), SAGA.Payments(), SAGA.Shipping(0.0, seed)
        self.log, self.dbs = SAGA.lab_helpers.SagaLog(), {n: OutboxDB(n) for n in ("orders", "payments", "shipping")}
        self.orch = SAGA.Orchestrator(self.orders, self.payments, self.shipping, self.log)
        self.orch.steps = [(n, self.outboxed(n, act), comp and self.outboxed(comp.__name__, comp))
                           for n, act, comp in self.orch.steps]  # every step and compensation goes through an outbox
        self.bus = Bus(self.rng, 0.2 if "bus-duplicates" in self.faults else 0.0)
        self.relay = Relay(list(self.dbs.values()), self.bus)
        self.emails, self.revenue, self.spans, self.trace, self.root = Counter(), defaultdict(int), [], {}, {}
        self.bus.subscribers += [IdempotentConsumer("email", self.email), IdempotentConsumer("revenue", self.book)]
        self.gateway, self.accepted, self.retries = BACKPRESSURE.Server(WORKERS, 1), {}, deque()
        self.queue_seen, self.waits, self.crashed, self.config_seen = [], [], set(), []

    def span(self, saga, name, parent):  # W3C-shaped ids from a seeded RNG (production: a CSPRNG)
        s = {"saga": saga, "name": name, "trace_id": self.trace[saga], "span_id": f"{self.rng.getrandbits(64):016x}",
             "parent_id": parent}
        self.spans.append(s)
        return s

    def outboxed(self, name, fn):
        """State change + its event in one local transaction, under a span whose traceparent rides on the event."""
        db = OWNER[name]
        state = {"orders": lambda s: self.orders.status.get(s), "payments": self.payments.net,
                 "shipping": lambda s: self.shipping.outcome.get(s)}[db]

        def step(saga, amount):
            faulty = saga in self.cohort
            if name == "ship" and faulty and "shipping-outage" in self.faults:
                self.shipping.outcome.setdefault(saga, "courier API down")  # fault: no courier for this order
            s = self.span(saga, f"{db}.{name}", self.root[saga])
            result = self.dbs[db].transact(lambda: fn(saga, amount), lambda: state(saga), EVENTS[name], saga,
                                           f"00-{s['trace_id']}-{s['span_id']}-01", amount=amount)
            if name == "charge" and faulty and "crash-after-charge" in self.faults and saga not in self.crashed:
                self.crashed.add(saga)
                raise SAGA.lab_helpers.Crash(f"orchestrator died after charge({saga})")  # fault: process dies
            return result
        step.__name__ = name
        return step

    def email(self, msg):
        self.consumer_span(msg, "email.send")
        self.emails[(msg["saga"], msg["type"])] += 1

    def book(self, msg):
        self.consumer_span(msg, "revenue.book")
        sign = {"payment.charged": 1, "payment.refunded": -1}.get(msg["type"], 0)
        self.revenue[msg["saga"]] += sign * msg["data"]["amount"]

    def consumer_span(self, msg, name):
        trace_id, parent, _ = TRACING.parse_traceparent(msg["traceparent"])  # context from the event header
        self.spans.append({"saga": msg["saga"], "name": name, "trace_id": trace_id,
                           "span_id": f"{self.rng.getrandbits(64):016x}", "parent_id": parent})

    def tick_config(self):
        """Operator: re-propose the wanted config until Raft commits it (the version makes retries idempotent);
        the pipeline applies only COMMITTED entries, and never an older version than it already has."""
        version = sum(k <= self.t for k in CONFIG_CHANGES)
        wanted = CONFIG_CHANGES[max(k for k in CONFIG_CHANGES if k <= self.t)]
        if "raft-leader-crash" in self.faults and self.t in (25, 40):
            if self.t == 25:
                self.downed = self.raft.leader().name
                self.raft.crash(self.downed)  # fault: the config leader dies just as the change arrives
            else:
                self.raft.restart(self.downed)
        leader = self.raft.leader()
        if leader:
            for _, cmd in leader.log[:leader.commit]:
                v, value = (int(x) for x in cmd.split(":"))
                if v > self.config["version"]:
                    self.config = {"version": v, "max_queue": value}
            if self.config["version"] < version and self.t % 5 == 0:
                leader.propose(f"{version}:{wanted}")
        self.gateway.max_queue = self.config["max_queue"]
        self.config_seen.append((self.t, self.config["version"]))
        self.raft.run(1)

    def submit(self, key, amount):
        """Client -> gateway with an idempotency key; on 503 the client retries after Retry-After (+ jitter)."""
        if key in self.accepted:
            return "duplicate"  # idempotent replay: the order exists, nothing new happens
        retry_after = self.gateway.admit(self.t)
        if retry_after is not None:  # bounded queue full: shed now, tell the client when to come back
            self.retries.append((self.t + retry_after + self.rng.randint(0, 2), key, amount))
            return "503"
        self.accepted[key] = amount
        self.gateway.queue.append((key, amount, self.t))
        self.span(key, "gateway.accept", self.root[key])
        if "lost-acks" in self.faults and self.rng.random() < 0.2:
            self.retries.append((self.t + 1, key, amount))  # the 200 got lost: the client retries anyway
        return "accepted"

    def run(self):
        arrivals = [(self.rng.randint(0, 30), f"o{i}", 10 * i) for i in range(1, N_ORDERS + 1)]
        arrivals += [(10, f"o{i}", 10 * i) for i in range(N_ORDERS + 1, N_ORDERS + 21)] if "burst" in self.faults else []
        for _, key, _ in arrivals:
            self.trace[key] = f"{self.rng.getrandbits(128):032x}"
            self.root[key] = self.span(key, "client.order", None)["span_id"]
        pending = deque(sorted(arrivals))
        while self.t < MAX_TICKS:
            self.tick_config()
            while pending and pending[0][0] <= self.t:
                self.submit(*pending.popleft()[1:])
            for due, key, amount in [self.retries.popleft() for _ in range(len(self.retries))]:
                if due <= self.t:
                    self.submit(key, amount)
                else:
                    self.retries.append((due, key, amount))
            self.queue_seen.append((len(self.gateway.queue), self.gateway.max_queue))
            for _ in range(min(WORKERS, len(self.gateway.queue))):
                key, amount, queued_at = self.gateway.queue.popleft()
                self.waits.append(self.t - queued_at)
                try:
                    self.orch.run(key, amount)
                except SAGA.lab_helpers.Crash:
                    self.orch.recover()  # the supervisor restarts it; it finishes from the saga log
            self.relay.crash_next = 1 if "relay-crash" in self.faults and self.t % 7 == 3 else 0
            self.relay.tick()
            self.t += 1
            settled = self.config["version"] == sum(k <= self.t for k in CONFIG_CHANGES)  # config change committed
            if settled and not (pending or self.retries or self.gateway.queue) and all(
                    r["sent"] for d in self.dbs.values() for r in d.rows):
                break
        self.raft.run(10)  # let followers learn the final commit index before anyone checks them
        return self


if __name__ == "__main__":
    p = Pipeline().run()
    done = Counter(r["status"] for r in p.log.entries() if r["step"] == "saga" and r["status"] != "started")
    print(f"ticks {p.t}, sagas {dict(done)}, events published {p.bus.published}, delivered {p.bus.delivered},"
          f" spans {len(p.spans)}, config {p.config}, audit: {SAGA.audit(p.orders, p.payments, p.shipping) or 'OK'}")
